function validate([queries, words]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 2000) return 'queries needs 1 to 2000 strings.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 2000) return 'words needs 1 to 2000 strings.';
  for (const s of queries.concat(words)) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 10) return 'Each string has 1 to 10 letters.';
    if (!/^[a-z]+$/.test(s)) return 'Strings use only lowercase English letters.';
  }
  return null;
}

