function numSmallerByFrequency(queries, words) {
  const score = (s) => {
    let smallest = s[0];
    let count = 0;
    for (const ch of s) {
      if (ch < smallest) {
        smallest = ch;
        count = 1;
      } else if (ch === smallest) {
        count++;
      }
    }
    return count;
  };

  const wordScores = words.map(score).sort((a, b) => a - b);
  const answer = [];

  for (const query of queries) {
    const target = score(query);
    let left = 0;
    let right = wordScores.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (wordScores[mid] <= target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    answer.push(wordScores.length - left);
  }
  return answer;
}

