function numSmallerByFrequency(queries, words) {
  // Score each string by sorting its letters and counting the run at the front.
  const f = (s) => {
    const sorted = s.split('').sort();
    let run = 0;
    while (run < sorted.length && sorted[run] === sorted[0]) run++;
    return run;
  };
  return queries.map(q => {
    const fq = f(q);
    let total = 0;
    for (const w of words) if (fq < f(w)) total++;
    return total;
  });
}

