function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const randomText = (alphabet) => {
    const length = 1 + Math.floor(rand() * 10);
    // Sometimes repeat one letter a lot so scores spread from 1 to 10.
    if (rand() < 0.3) {
      const base = alphabet[Math.floor(rand() * alphabet.length)];
      return Array.from({ length }, () => (rand() < 0.7 ? base : alphabet[Math.floor(rand() * alphabet.length)])).join('');
    }
    return Array.from({ length }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('');
  };
  if (size === 'large') {
    const alphabet = letters.slice(0, 2 + Math.floor(rand() * 25));
    const queries = Array.from({ length: 2000 }, () => randomText(alphabet));
    const words = Array.from({ length: 2000 }, () => randomText(alphabet));
    return [queries, words];
  }
  const alphabet = letters.slice(0, 1 + Math.floor(rand() * 4));
  const queries = Array.from({ length: 1 + Math.floor(rand() * 5) }, () => randomText(alphabet));
  const words = Array.from({ length: 1 + Math.floor(rand() * 6) }, () => randomText(alphabet));
  return [queries, words];
}
